// German translation. English text is the key: every <Txt> passes its string children through t(),
// so screens stay readable in English while the app renders in the user's language.
import { getLocales } from 'expo-localization';

export type Lang = 'en' | 'de';
// Before login (welcome, login): the phone's language. Once signed in, the profile's setting takes over.
let current: Lang = resolveLang('auto');

export function resolveLang(pref: 'auto' | 'en' | 'de' | undefined): Lang {
  if (pref === 'en' || pref === 'de') return pref;
  try {
    return getLocales()[0]?.languageCode === 'de' ? 'de' : 'en';
  } catch {
    return 'en';
  }
}
export const setLang = (l: Lang) => { current = l; };
export const getLang = () => current;
export const locale = () => (current === 'de' ? 'de-DE' : 'en-GB');

